import "@stdlib/strings"
import "errors"
import "fees"
import "messages"
import "types"

contract NftCollection {
    author: "Pirate Station"
    version: "1.0"
    description: "Pirate Station NFT Collection with public mint. TEP-62 and TEP-64 compatible"
    storage: NftCollectionStorage
    incomingMessages: AllowedMessageToNftCollection
}

type AllowedMessageToNftCollection =
    | Mint
    | AdminMint
    | RequestRoyaltyParams
    | ChangeCollectionAdmin
    | ChangeCollectionContent
    | ChangeMintPrice
    | WithdrawFunds

// Deploy the next NFT item to `recipient`. All items share the same (empty)
// individual content, so every NFT resolves to the same off-chain metadata.
fun deployNftItem(itemIndex: uint64, nftItemCode: cell, recipient: address) {
    val deployMsg = createMessage({
        bounce: BounceMode.Only256BitsOfBody,
        dest: calcDeployedNftItem(itemIndex, contract.getAddress(), nftItemCode),
        value: NFT_DEPLOY_AMOUNT,
        body: NftItemInitAtDeployment { ownerAddress: recipient, content: "" },
    });
    deployMsg.send(SEND_MODE_PAY_FEES_SEPARATELY);
}

fun onInternalMessage(in: InMessage) {
    val msg = lazy AllowedMessageToNftCollection.fromSlice(in.body);

    match (msg) {
        Mint => {
            var storage = lazy NftCollectionStorage.load();
            assert (storage.nextItemIndex < storage.maxSupply) throw Errors.SoldOut;
            assert (in.valueCoins >= storage.mintPrice) throw Errors.InsufficientPayment;

            deployNftItem(storage.nextItemIndex, storage.nftItemCode, in.senderAddress);
            storage.nextItemIndex += 1;
            storage.save();
        }

        AdminMint => {
            var storage = lazy NftCollectionStorage.load();
            assert (in.senderAddress == storage.adminAddress) throw Errors.NotFromAdmin;
            assert (storage.nextItemIndex < storage.maxSupply) throw Errors.SoldOut;

            deployNftItem(storage.nextItemIndex, storage.nftItemCode, msg.recipient);
            storage.nextItemIndex += 1;
            storage.save();
        }

        RequestRoyaltyParams => {
            val storage = lazy NftCollectionStorage.load();
            val respondMsg = createMessage({
                bounce: BounceMode.NoBounce,
                dest: in.senderAddress,
                value: 0,
                body: ResponseRoyaltyParams {
                    queryId: msg.queryId,
                    royaltyParams: storage.royaltyParams.load(),
                },
            });
            respondMsg.send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE);
        }

        ChangeCollectionAdmin => {
            var storage = lazy NftCollectionStorage.load();
            assert (in.senderAddress == storage.adminAddress) throw Errors.NotFromAdmin;
            storage.adminAddress = msg.newAdminAddress;
            storage.save();
        }

        ChangeCollectionContent => {
            var storage = lazy NftCollectionStorage.load();
            assert (in.senderAddress == storage.adminAddress) throw Errors.NotFromAdmin;
            storage.content = msg.newContent;
            storage.save();
        }

        ChangeMintPrice => {
            var storage = lazy NftCollectionStorage.load();
            assert (in.senderAddress == storage.adminAddress) throw Errors.NotFromAdmin;
            storage.mintPrice = msg.newMintPrice;
            storage.save();
        }

        WithdrawFunds => {
            val storage = lazy NftCollectionStorage.load();
            assert (in.senderAddress == storage.adminAddress) throw Errors.NotFromAdmin;

            val amount = contract.getOriginalBalance() - MIN_TONS_FOR_STORAGE;
            assert (amount > 0) throw Errors.TooSmallRestAmount;

            val withdrawMsg = createMessage({
                bounce: BounceMode.NoBounce,
                dest: storage.adminAddress,
                value: amount,
                body: ReturnExcessesBack { queryId: msg.queryId },
            });
            withdrawMsg.send(SEND_MODE_REGULAR);
        }

        else => {
            // ignore empty messages (balance top-ups), reject unknown opcodes
            assert (in.body.isEmpty()) throw 0xFFFF;
        }
    }
}

fun onBouncedMessage(_in: InMessageBounced) {
    // receive funds back from a possibly bounced item deployment
}

get fun get_collection_data(): CollectionDataReply {
    val storage = lazy NftCollectionStorage.load();
    val content = lazy storage.content.load();
    return {
        nextItemIndex: storage.nextItemIndex,
        collectionMetadata: content.collectionMetadata,
        adminAddress: storage.adminAddress,
    };
}

get fun get_nft_address_by_index(itemIndex: int): address {
    val storage = lazy NftCollectionStorage.load();
    val nftDeployed = calcDeployedNftItem(itemIndex, contract.getAddress(), storage.nftItemCode);
    return nftDeployed.calculateAddress();
}

get fun royalty_params(): RoyaltyParams {
    val storage = lazy NftCollectionStorage.load();
    return storage.royaltyParams.load();
}

get fun get_nft_content(
    _itemIndex: int,
    individualNftContent: string,
): Cell<OffchainMetadataReply> {
    val storage = lazy NftCollectionStorage.load();
    val content = lazy storage.content.load();

    // full metadata URL = commonContent + individualNftContent;
    // for identical items individualNftContent is empty, so all resolve to commonContent
    var b = StringBuilder.create();
    b.append(content.commonContent);
    b.append(individualNftContent);
    return OffchainMetadataReply { string: b.build() }.toCell();
}

get fun get_mint_data(): MintDataReply {
    val storage = lazy NftCollectionStorage.load();
    return {
        nextItemIndex: storage.nextItemIndex,
        maxSupply: storage.maxSupply,
        mintPrice: storage.mintPrice,
        adminAddress: storage.adminAddress,
    };
}

// Minimal Toncoin kept on a contract balance to pay storage rent.
const MIN_TONS_FOR_STORAGE = ton("0.05")

// Toncoin attached to each NFT item deployment (storage + deploy fees).
// The rest of the mint payment stays on the collection balance as revenue.
const NFT_DEPLOY_AMOUNT = ton("0.06")

import "types"

// Body the collection sends to a freshly deployed item to initialize it.
struct NftItemInitAtDeployment {
    ownerAddress: address
    content: string
}

// --- Collection: incoming ---

// Public mint: anyone who attaches >= mintPrice receives the next NFT.
struct (0x4d696e74) Mint {
    queryId: uint64
}

// Admin-only free mint to an arbitrary address (rewards / giveaways).
struct (0x00000007) AdminMint {
    queryId: uint64
    recipient: address
}

struct (0x693d3950) RequestRoyaltyParams {
    queryId: uint64
}

struct (0x00000003) ChangeCollectionAdmin {
    queryId: uint64
    newAdminAddress: address
}

// Update off-chain content URLs (e.g. switch host to bunny.net later).
struct (0x00000004) ChangeCollectionContent {
    queryId: uint64
    newContent: Cell<CollectionContent>
}

struct (0x00000005) ChangeMintPrice {
    queryId: uint64
    newMintPrice: coins
}

// Send accumulated mint revenue to the admin (keeps storage reserve).
struct (0x00000006) WithdrawFunds {
    queryId: uint64
}

// --- Collection: outgoing ---

struct (0xa8cb00ad) ResponseRoyaltyParams {
    queryId: uint64
    royaltyParams: RoyaltyParams
}

// --- Item ---

struct (0x2fcb26a2) RequestStaticData {
    queryId: uint64
}

struct (0x8b771735) ResponseStaticData {
    queryId: uint64
    itemIndex: uint256
    collectionAddress: address
}

struct (0b0) PayloadInline {
    value: RemainingBitsAndRefs
}

struct (0b1) PayloadInRef {
    value: Cell<RemainingBitsAndRefs>
}

struct (0x05138d91) NotificationForNewOwner {
    queryId: uint64
    oldOwnerAddress: address
    @abi.clientType(PayloadInline | PayloadInRef)
    payload: RemainingBitsAndRefs
}

struct (0xd53276db) ReturnExcessesBack {
    queryId: uint64
}

struct (0x5fcc3d14) AskToChangeOwnership {
    queryId: uint64
    newOwnerAddress: address
    sendExcessesTo: address?
    customPayload: cell?
    forwardTonAmount: coins
    @abi.clientType(PayloadInline | PayloadInRef)
    forwardPayload: RemainingBitsAndRefs
}

struct RoyaltyParams {
    numerator: uint16
    denominator: uint16
    royaltyAddress: address
}

struct CollectionContent {
    collectionMetadata: cell
    commonContent: string
}

struct NftCollectionStorage {
    adminAddress: address
    nextItemIndex: uint64
    content: Cell<CollectionContent>
    nftItemCode: cell
    royaltyParams: Cell<RoyaltyParams>
    mintPrice: coins
    maxSupply: uint64
}

fun NftCollectionStorage.load(): NftCollectionStorage {
    return NftCollectionStorage.fromCell(contract.getData());
}

fun NftCollectionStorage.save(self) {
    contract.setData(self.toCell());
}

// NFT item storage is tricky: it changes shape after deployment.
// Initially it holds only itemIndex + collectionAddress (NftItemStorageNotInitialized);
// after the collection initializes it, it becomes a full NftItemStorage.
struct NftItemStorage {
    itemIndex: uint64
    collectionAddress: address
    ownerAddress: address
    content: string
}

struct NftItemStorageNotInitialized {
    itemIndex: uint64
    collectionAddress: address
}

struct NftItemStorageLoader {
    itemIndex: uint64
    collectionAddress: address
    private rest: RemainingBitsAndRefs
}

fun NftItemStorage.startLoading(): NftItemStorageLoader {
    return NftItemStorageLoader.fromCell(contract.getData());
}

fun NftItemStorage.save(self) {
    contract.setData(self.toCell());
}

fun NftItemStorageLoader.isNotInitialized(self): bool {
    return self.rest.isEmpty();
}

fun NftItemStorageLoader.endLoading(mutate self): NftItemStorage {
    return {
        itemIndex: self.itemIndex,
        collectionAddress: self.collectionAddress,
        ownerAddress: self.rest.loadAny(),
        content: self.rest.loadAny(),
    };
}

fun calcDeployedNftItem(
    itemIndex: uint64,
    collectionAddress: address,
    nftItemCode: cell,
): AutoDeployAddress {
    val emptyNftItemStorage: NftItemStorageNotInitialized = { itemIndex, collectionAddress };
    return { stateInit: { code: nftItemCode, data: emptyNftItemStorage.toCell() } };
}

struct CollectionDataReply {
    nextItemIndex: int
    collectionMetadata: cell
    adminAddress: address
}

struct MintDataReply {
    nextItemIndex: int
    maxSupply: int
    mintPrice: coins
    adminAddress: address
}

struct NftDataReply {
    isInitialized: bool
    itemIndex: int
    collectionAddress: address
    ownerAddress: address? = null
    content: string? = null
}

struct (0x01) OffchainMetadataReply {
    string: string
}
